'use strict';
const $=id=>document.getElementById(id),clone=x=>JSON.parse(JSON.stringify(x));
let data=null,list=null,path=null,handle=null,fileName='lists.json',baseline='',originalText='',indent='\t',newline='\n',trailing=true,history=[],future=[];
const own=(o,k)=>Object.prototype.hasOwnProperty.call(o,k);
const serial=()=>JSON.stringify(data);
const dirty=()=>data&&serial()!==baseline;
function validate(x){
 const object=o=>o&&typeof o==='object'&&!Array.isArray(o);
 function node(v,where,item=false){if(!object(v))throw Error(where+' must be an object.');if(item&&typeof v.text!=='string')throw Error(where+' must have a text string.');if(own(v,'ref')&&!Number.isSafeInteger(v.ref))throw Error(where+': reference must be a safe integer.');if(own(v,'lineHeight')&&(!Number.isInteger(v.lineHeight)||v.lineHeight<1))throw Error(where+': line height must be a positive integer.');for(const k of ['editable','collapsed'])if(own(v,k)&&typeof v[k]!=='boolean')throw Error(where+': '+k+' must be true or false.');if(own(v,'items')){if(!Array.isArray(v.items))throw Error(where+': items must be an array.');v.items.forEach((a,i)=>node(a,where+' / '+i,true));}}
 if(!object(x))throw Error('Expected a JSON object containing named lists.');Object.entries(x).forEach(([k,v])=>node(v,k));return x;
}
function entry(){let n=data?.[list];for(const i of path||[])n=n?.items?.[i];return path?n:null;}
function parent(){let n=data[list];for(const i of (path||[]).slice(0,-1))n=n.items[i];return n;}
function snapshot(){return {data:clone(data),list,path:path?.slice()??null};}
function change(fn){const before=snapshot();try{fn();validate(data);}catch(e){data=before.data;list=before.list;path=before.path;alert(e.message);return;}history.push(before);if(history.length>100)history.shift();future=[];render();}
function restore(from,to){if(!from.length)return;to.push(snapshot());const s=from.pop();data=s.data;list=s.list;path=s.path;render();}
function count(n){return(n.items||[]).reduce((s,i)=>s+1+count(i),0);}
function row(text,ref,selected,click,depth=0){const b=document.createElement('button');b.className='row'+(selected?' selected':'');b.style.paddingLeft=10+depth*18+'px';const n=document.createElement('span');n.className='name';n.textContent=text;const r=document.createElement('span');r.className='ref';r.textContent=ref;b.append(n,r);b.onclick=click;return b;}
function renderLists(){const box=$('lists');box.replaceChildren();if(!data)return;const q=$('listSearch').value.toLowerCase();Object.keys(data).sort((a,b)=>a.localeCompare(b)).filter(k=>k.toLowerCase().includes(q)).forEach(k=>box.append(row(k,count(data[k]),k===list,()=>{list=k;path=data[k].items?.length?[0]:null;$('itemSearch').value='';render();})));if(!box.children.length)box.textContent='No matching lists.';}
function renderItems(){if(!data)return;const box=$('items');box.replaceChildren();const q=$('itemSearch').value.toLowerCase();function walk(n,p=[]){(n.items||[]).forEach((e,i)=>{const pp=[...p,i];if(e.text.toLowerCase().includes(q)||String(e.ref??'').includes(q))box.append(row((e.items?.length?'▾ ':'')+e.text,e.ref??'',JSON.stringify(pp)===JSON.stringify(path),()=>{path=pp;render();},p.length));walk(e,pp);});}if(list)walk(data[list]);if(!box.children.length){const e=document.createElement('div');e.className='empty';e.textContent=q?'No matching entries.':list?'This list is empty. Add your first entry below.':'Add a list to get started.';box.append(e);}}
function render(){renderLists();renderItems();const l=data?.[list],e=entry();$('listCount').textContent=data?Object.keys(data).length:0;$('itemCount').textContent=l?count(l):0;$('selectedList').textContent=list||'Your lists, organized.';$('noSelection').classList.toggle('hidden',!!l);$('properties').classList.toggle('hidden',!l);$('entryFields').classList.toggle('hidden',!e);for(const k of ['text','ref','icon'])$(k).value=e?.[k]??'';for(const k of ['editable','collapsed'])$(k).checked=!!e?.[k];$('lineHeight').value=l?.lineHeight??18;$('listEditable').checked=!!l?.editable;
 for(const k of ['save','addList'])$(k).disabled=!data;for(const k of ['deleteList','renameList','addItem'])$(k).disabled=!l;for(const k of ['deleteItem','duplicate','addChild','up','down'])$(k).disabled=!e;if(e){const i=path.at(-1);$('up').disabled=i===0;$('down').disabled=i===parent().items.length-1;}$('undo').disabled=!history.length;$('redo').disabled=!future.length;$('fileName').textContent=fileName+(dirty()?' •':'');$('total').textContent=data?Object.keys(data).length+' lists · '+Object.values(data).reduce((a,l)=>a+count(l),0)+' entries':'4D list editor';$('status').textContent=dirty()?'Unsaved changes':data?'No unsaved changes':'Ready';}
function modal(title,content,fn,label='Apply'){$('modalTitle').textContent=title;$('modalBody').replaceChildren(content);$('modalError').textContent='';$('confirm').textContent=label;$('confirm').onclick=()=>{try{fn();$('modal').close();}catch(e){$('modalError').textContent=e.message;}};$('modal').showModal();content.focus?.();}
function textModal(title,value,fn){const input=document.createElement('input');input.value=value;modal(title,input,()=>fn(input.value));input.select();}
function confirmModal(title,description,fn){const p=document.createElement('p');p.textContent=description;modal(title,p,fn,'Delete');}
$('cancel').onclick=()=>$('modal').close();
function nameCheck(n){if(!n.trim())throw Error('Enter a list name.');if(own(data,n))throw Error('A list with this name already exists.');}
$('addList').onclick=()=>textModal('New list','',n=>{nameCheck(n);change(()=>{Object.defineProperty(data,n,{value:{lineHeight:18,editable:true,items:[]},enumerable:true,writable:true,configurable:true});list=n;path=null;});});
$('renameList').onclick=()=>textModal('Rename list',list,n=>{if(n===list)return;nameCheck(n);change(()=>{data=Object.fromEntries(Object.entries(data).map(([k,v])=>[k===list?n:k,v]));list=n;});});
$('deleteList').onclick=()=>confirmModal('Delete “'+list+'”?','This removes the list and all its entries. You can undo this change.',()=>change(()=>{delete data[list];list=Object.keys(data)[0]??null;path=null;}));
function nextRef(){let max=0;function scan(n){for(const e of n.items||[]){if(Number.isSafeInteger(e.ref))max=Math.max(max,e.ref);scan(e);}}scan(data[list]);return max<Number.MAX_SAFE_INTEGER?max+1:0;}
$('addItem').onclick=()=>textModal('New entry','New item',text=>change(()=>{const l=data[list];l.items??=[];l.items.push({text,ref:nextRef(),editable:true});path=[l.items.length-1];$('itemSearch').value='';}));
$('addChild').onclick=()=>textModal('New child entry','New item',text=>change(()=>{const e=entry();e.items??=[];e.items.push({text,ref:nextRef(),editable:true});path=[...path,e.items.length-1];$('itemSearch').value='';}));
$('deleteItem').onclick=()=>confirmModal('Delete entry?','This removes the selected entry and any children. You can undo this change.',()=>change(()=>{const a=parent().items,i=path.at(-1);a.splice(i,1);path=a.length?[...path.slice(0,-1),Math.min(i,a.length-1)]:path.length>1?path.slice(0,-1):null;}));
$('duplicate').onclick=()=>change(()=>{const a=parent().items,i=path.at(-1),e=clone(entry());e.text+=' copy';function refs(n){n.ref=nextRef();for(const c of n.items||[])refs(c);}a.splice(i+1,0,e);refs(e);path[path.length-1]=i+1;});
for(const [id,d] of [['up',-1],['down',1]])$(id).onclick=()=>change(()=>{const a=parent().items,i=path.at(-1);[a[i],a[i+d]]=[a[i+d],a[i]];path[path.length-1]+=d;});
for(const k of ['text','icon'])$(k).onchange=()=>{const value=$(k).value;change(()=>{if(k==='icon'&&!value)delete entry()[k];else entry()[k]=value;});};
$('ref').onchange=()=>{const value=$('ref').value;change(()=>{if(value==='')throw Error('Reference cannot be blank.');entry().ref=Number(value);});};
for(const k of ['editable','collapsed'])$(k).onchange=()=>{const value=$(k).checked;change(()=>entry()[k]=value);};
$('lineHeight').onchange=()=>{const n=Number($('lineHeight').value);change(()=>data[list].lineHeight=n);};$('listEditable').onchange=()=>{const v=$('listEditable').checked;change(()=>data[list].editable=v);};
$('advanced').onclick=()=>{const t=document.createElement('textarea');t.value=JSON.stringify(entry()||data[list],null,2);t.setAttribute('aria-label','Raw JSON properties');modal(entry()?'Entry JSON':'List JSON',t,()=>{const v=JSON.parse(t.value),test=clone(data);if(path){let p=test[list];for(const i of path.slice(0,-1))p=p.items[i];p.items[path.at(-1)]=v;}else test[list]=v;validate(test);change(()=>{data=test;});});};
$('listSearch').oninput=renderLists;$('itemSearch').oninput=renderItems;$('undo').onclick=()=>restore(history,future);$('redo').onclick=()=>restore(future,history);
async function load(file,h=null){try{const text=await file.text(),parsed=validate(JSON.parse(text.replace(/^\uFEFF/,'')));if(dirty()&&!confirm('Discard unsaved changes and open another file?'))return;data=parsed;list=own(data,'All_Users')?'All_Users':Object.keys(data).sort()[0]??null;path=data[list]?.items?.length?[0]:null;handle=h;fileName=file.name;originalText=text;baseline=serial();history=[];future=[];indent=text.match(/\n([\t ]+)"/)?.[1]??'\t';newline=text.includes('\r\n')?'\r\n':'\n';trailing=/\r?\n$/.test(text);$('listSearch').value='';$('itemSearch').value='';render();}catch(e){alert('Could not open file: '+e.message);}}
async function openFile(){try{if(window.showOpenFilePicker){const [h]=await showOpenFilePicker({types:[{description:'JSON lists',accept:{'application/json':['.json']}}],multiple:false});await load(await h.getFile(),h);}else $('file').click();}catch(e){if(e.name!=='AbortError'){if(e.name==='SecurityError')$('file').click();else alert(e.message);}}}
$('open').onclick=openFile;$('emptyOpen').onclick=openFile;$('file').onchange=async e=>{if(e.target.files[0])await load(e.target.files[0]);e.target.value='';};
function output(){if(!dirty())return originalText;return JSON.stringify(data,null,indent).replace(/\n/g,newline)+(trailing?newline:'');}
async function save(){if(!data)return;try{validate(data);const text=output();if(handle){const current=await(await handle.getFile()).text();if(current!==originalText)throw Error('The file changed on disk since you opened it. Reopen the current file before saving to avoid overwriting external edits.');const w=await handle.createWritable();await w.write(text);await w.close();originalText=text;baseline=serial();render();$('status').textContent='Saved to '+fileName;}else{const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=fileName;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);$('status').textContent='Download created · keep it before closing';}}catch(e){alert('Could not save: '+e.message);}}
$('save').onclick=save;window.addEventListener('beforeunload',e=>{if(dirty()){e.preventDefault();e.returnValue='';}});window.addEventListener('dragover',e=>e.preventDefault());window.addEventListener('drop',e=>{e.preventDefault();if(e.dataTransfer.files[0])load(e.dataTransfer.files[0]);});window.addEventListener('keydown',e=>{if(!(e.metaKey||e.ctrlKey))return;if(e.key.toLowerCase()==='s'){e.preventDefault();document.activeElement?.blur();save();}if(e.key.toLowerCase()==='z'&&!['INPUT','TEXTAREA'].includes(e.target.tagName)){e.preventDefault();restore(e.shiftKey?future:history,e.shiftKey?history:future);}});
